package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.contact.ContactImportJobState;
import cn.mop.domain.contact.ContactImportJobState.*;
import java.time.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ContactImportJobStateTest {
    static final Instant NOW=Instant.parse("2026-10-03T18:00:00Z");
    ContactImportJobState queued(){return ContactImportJobState.queued(3,NOW);}
    ContactImportJobState leased(){return queued().claim("worker-1",NOW,Duration.ofSeconds(30)).orElseThrow();}
    @Test void queuedStateHasNoCompletionLeaseOrDefaultExecution(){var q=queued();assertEquals(State.PENDING,q.state());assertEquals("QUEUED",q.step());assertEquals(0,q.attempts());assertEquals(0,q.fencingToken());assertNull(q.completedRows());assertNull(q.leaseOwner());assertNull(q.error());assertFalse(q.terminal());}
    @Test void claimBeforeExplicitDueTimeDoesNothing(){assertTrue(queued().claim("worker-1",NOW.minusMillis(1),Duration.ofSeconds(30)).isEmpty());assertEquals(0,queued().attempts());}
    @Test void dueClaimIncrementsCounterAndPinsOwnerExpiry(){var l=leased();assertEquals(State.LEASED,l.state());assertEquals("APPLYING",l.step());assertEquals(1,l.attempts());assertEquals(1,l.fencingToken());assertEquals("worker-1",l.leaseOwner());assertEquals(NOW.plusSeconds(30),l.leaseUntil());assertNull(l.nextAt());}
    @Test void activeLeaseCannotBeTakenButExactExpiryCanBeReclaimed(){var l=leased();assertTrue(l.claim("worker-2",NOW.plusSeconds(29),Duration.ofSeconds(30)).isEmpty());var next=l.claim("worker-2",NOW.plusSeconds(30),Duration.ofSeconds(30)).orElseThrow();assertEquals(2,next.fencingToken());assertEquals(2,next.attempts());assertEquals("worker-2",next.leaseOwner());}
    @Test void staleWorkerAndFenceCannotCompleteReclaimedWork(){var l=leased().claim("worker-2",NOW.plusSeconds(30),Duration.ofSeconds(30)).orElseThrow();assertEquals("STALE_IMPORT_LEASE",assertThrows(DomainException.class,()->l.succeed("worker-1",1,NOW.plusSeconds(31),3)).code);assertThrows(DomainException.class,()->l.succeed("worker-2",1,NOW.plusSeconds(31),3));assertEquals(State.SUCCEEDED,l.succeed("worker-2",2,NOW.plusSeconds(31),3).state());}
    @Test void successRequiresExactWholeBatchAndClearsLease(){var l=leased();assertThrows(DomainException.class,()->l.succeed("worker-1",1,NOW.plusSeconds(1),2));assertThrows(DomainException.class,()->l.succeed("worker-1",1,NOW.plusSeconds(1),4));var result=l.succeed("worker-1",1,NOW.plusSeconds(1),3);assertEquals(3,result.completedRows());assertEquals("APPLIED",result.step());assertNull(result.leaseUntil());assertTrue(result.terminal());}
    @Test void expiredLeaseCannotCompleteRetryOrFailAtBoundary(){var l=leased();Instant expiry=NOW.plusSeconds(30);assertThrows(DomainException.class,()->l.succeed("worker-1",1,expiry,3));assertThrows(DomainException.class,()->l.retry("worker-1",1,expiry,expiry.plusSeconds(30)));assertThrows(DomainException.class,()->l.fail("worker-1",1,expiry,Failure.PAYLOAD_INVALID));}
    @Test void transientRetryPreservesCountersAndNeedsExplicitFutureSchedule(){var q=leased().retry("worker-1",1,NOW.plusSeconds(1),NOW.plusSeconds(10));assertEquals(State.PENDING,q.state());assertEquals("RETRY_WAIT",q.step());assertEquals(Failure.UPSTREAM_UNAVAILABLE,q.error());assertEquals(1,q.attempts());assertEquals(1,q.fencingToken());assertNull(q.leaseOwner());assertTrue(q.claim("worker-2",NOW.plusSeconds(9),Duration.ofSeconds(20)).isEmpty());var l=q.claim("worker-2",NOW.plusSeconds(10),Duration.ofSeconds(20)).orElseThrow();assertEquals(2,l.attempts());assertNull(l.error());}
    @Test void retryAtPresentPastOrUnknownRejected(){var l=leased();for(Instant next:new Instant[]{null,NOW,NOW.minusSeconds(1)})assertThrows(DomainException.class,()->l.retry("worker-1",1,NOW,next));}
    @Test void permanentBusinessOrAuthorizationFailureIsExplicitAndNoPartialSuccess(){for(Failure reason:new Failure[]{Failure.AUTHORIZATION_REVOKED,Failure.PAYLOAD_INVALID,Failure.LAST_ENABLED_DECISION_MAKER}){var f=leased().fail("worker-1",1,NOW,reason);assertEquals(State.FAILED,f.state());assertEquals(reason.name(),f.step());assertNull(f.completedRows());assertTrue(f.terminal());}assertThrows(DomainException.class,()->leased().fail("worker-1",1,NOW,Failure.UPSTREAM_UNAVAILABLE));}
    @Test void terminalJobsCannotBeClaimedAgainOrCompletedTwice(){var s=leased().succeed("worker-1",1,NOW,3);var f=leased().fail("worker-1",1,NOW,Failure.PAYLOAD_INVALID);for(var end:new ContactImportJobState[]{s,f}){assertTrue(end.claim("worker-2",NOW.plusSeconds(100),Duration.ofSeconds(30)).isEmpty());assertThrows(DomainException.class,()->end.succeed("worker-1",1,NOW,3));}}
    @Test void inconsistentPersistedStateRejectedRatherThanProjectedAsNormal(){assertThrows(DomainException.class,()->new ContactImportJobState(State.PENDING,3,1,0,null,null,null,NOW,null,Failure.UPSTREAM_UNAVAILABLE));assertThrows(DomainException.class,()->new ContactImportJobState(State.SUCCEEDED,3,1,1,null,null,null,null,2,null));assertThrows(DomainException.class,()->new ContactImportJobState(State.LEASED,3,0,0,"worker",NOW,NOW.plusSeconds(1),null,null,null));assertThrows(DomainException.class,()->new ContactImportJobState(State.FAILED,3,1,1,null,null,null,null,0,Failure.PAYLOAD_INVALID));}
    @Test void countAndCounterBoundsFailClosedWithoutOverflow(){for(int count:new int[]{0,101})assertThrows(DomainException.class,()->ContactImportJobState.queued(count,NOW));var max=new ContactImportJobState(State.PENDING,1,ContactImportJobState.MAX_COUNTER,ContactImportJobState.MAX_COUNTER,null,null,null,NOW,null,Failure.UPSTREAM_UNAVAILABLE);assertEquals("IMPORT_LEASE_COUNTER_EXHAUSTED",assertThrows(DomainException.class,()->max.claim("worker",NOW,Duration.ofSeconds(1))).code);}
    @Test void workerAndDurationAreExplicitBoundedIdentifiersWithoutPaths(){for(String worker:new String[]{null,"","/path","with space","x".repeat(65)})assertThrows(DomainException.class,()->queued().claim(worker,NOW,Duration.ofSeconds(1)));for(Duration duration:new Duration[]{null,Duration.ZERO,Duration.ofSeconds(-1),Duration.ofNanos(1),Duration.ofHours(1).plusMillis(1),Duration.ofSeconds(Long.MAX_VALUE)})assertThrows(DomainException.class,()->queued().claim("worker",NOW,duration));assertTrue(queued().claim("worker",NOW,Duration.ofHours(1)).isPresent());}
    @Test void timestampPrecisionRangeAndExpiryOverflowRejected(){assertThrows(DomainException.class,()->ContactImportJobState.queued(1,NOW.plusNanos(1)));assertThrows(DomainException.class,()->ContactImportJobState.queued(1,Instant.parse("0000-12-31T23:59:59Z")));Instant end=Instant.parse("9999-12-31T23:59:59.999Z");assertThrows(DomainException.class,()->ContactImportJobState.queued(1,end).claim("worker",end,Duration.ofMillis(1)));}
    @Test void completionBeforeLeaseStartAndInvertedPersistedLeaseRejected(){var l=leased();assertEquals(NOW,l.leaseStartedAt());assertThrows(DomainException.class,()->l.succeed("worker-1",1,NOW.minusMillis(1),3));assertThrows(DomainException.class,()->new ContactImportJobState(State.LEASED,3,1,1,"worker",NOW,NOW,null,null,null));}

}
